<div class="mb-5 flex justify-end"><a class="rounded-2xl bg-emerald-600 px-5 py-3 font-black text-white" href="<?= e(app_url('product-create', [], 'admin')) ?>">Add Product</a></div><div class="overflow-x-auto rounded-3xl border border-slate-200 bg-white"><table class="admin-table"><tr><th>Product</th><th>Category</th><th>Version</th><th>Updated</th><th>Price</th><th>Actions</th></tr><?php foreach ($products as $product): ?><tr><td><b><?= e($product['name']) ?></b><p class="text-xs text-slate-500"><?= e($product['short_description']) ?></p></td><td><?= e($product['category_name']) ?></td><td><?= e($product['version']) ?></td><td><?= e($product['last_updated']) ?></td><td><?= money($product['sale_price'] ?: $product['regular_price']) ?></td><td><a class="text-emerald-600" href="<?= e(app_url('product-edit', ['id' => $product['id']], 'admin')) ?>">Edit</a></td></tr><?php endforeach; ?></table></div>
